+bool GatedDeltaUpdate::use_fallback(
+    const int Hk,
+    const int Dk,
+    const int Hv,
+    const int Dv,
+    const bool has_mask,
+    Stream s) {
+  if (s.device == Device::cpu) {
+    return true;
+  }
+  if (has_mask) {
+    return true;
+  }
+  return !supported_gated_delta_shape(Hk, Dk, Hv, Dv);
+}
