+    }
+  }
+
+  if (stage_fp32) {
+    copy_gpu(dq_acc, dq, CopyType::General, s);
+    copy_gpu(dk_acc, dk, CopyType::General, s);
+    copy_gpu(dv_acc, dv, CopyType::General, s);
+    copy_gpu(dg_acc, dg, CopyType::General, s);
+    copy_gpu(db_acc, db, CopyType::General, s);
+  }
+}
