+  int y_n = targets[gid];
+  y_n = (y_n < 0) ? y_n + axis_size : y_n;
+  AccT x_t = AccT(in[y_n]);
+  AccT g = AccT(cotan[gid]);
+  AccT l = AccT(loss[gid]);
