+    } else {
+      for (int i = 0; i < N_READS; i++) {
+        int col = offset + i;
+        if (col < axis_size) {
+          AccT p = fast::exp((AccT(in[col]) - x_t) - l);
+          out[col] = T(g * (p - ((col == y_n) ? AccT(1) : AccT(0))));
+        }
+      }
+    }
+  }
+}

