+  const int b_idx = n / Hv;
+  const int hv_idx = n % Hv;
+  const int base = b_idx * T * Hv + hv_idx;
+
+  float acc = 0.0f;
+  for (int j = len - 1; j >= 0; --j) {
+    const int idx = base + (t0 + j) * Hv;
+    acc += static_cast<float>(dg[idx]);
+    float gv = metal::max(static_cast<float>(g[idx]), 1e-6f);
+    dg[idx] = acc / gv;
+  }
+}

